做一个chrome的插件，使用 bun react vite  tailwindcss shadcn-ui oxlint oxfmt .

目标是针对网站读取indexdb查询需要的数据

```js
const targetChannelId = "019c7a04-3cb3-719a-9151-cfe443368985";

const dbReq = indexedDB.open('FinAgentDB');

dbReq.onsuccess = async event => {
  const db = event.target.result;
  const tx = db.transaction('conversations', 'readonly');
  const store = tx.objectStore('conversations');

  const all = await new Promise(resolve => {
    const req = store.getAll();
    req.onsuccess = () => resolve(req.result);
  });

  console.log(all.filter(x => x.channelId === targetChannelId));
};


