export type QueryErrorCode =
  | "NO_ACTIVE_TAB"
  | "INVALID_URL"
  | "UNSUPPORTED_PAGE"
  | "INJECTION_FAILED"
  | "DB_OPEN_FAILED"
  | "STORE_MISSING"
  | "NOT_FOUND"
  | "SESSION_ID_MISSING"
  | "CLIPBOARD_FAILED";

export type ConversationRecord = {
  channelId: string;
  sessionId?: string;
  title?: string;
  updatedAt?: string;
  timestamp?: string;
};

export type SessionLookupSuccess = {
  ok: true;
  channelId: string;
  sessionId: string;
  command: string;
  title?: string;
  updatedAt?: string;
};

export type SessionLookupFailure = {
  ok: false;
  code: QueryErrorCode;
  message: string;
};

export type SessionLookupResult = SessionLookupSuccess | SessionLookupFailure;

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

import type { SessionLookupFailure } from "@/types/session";

export async function getActiveTab(): Promise<chrome.tabs.Tab | null> {
  const [tab] = await chrome.tabs.query({
    active: true,
    lastFocusedWindow: true,
  });

  return tab ?? null;
}

export function isInjectablePage(url: string): boolean {
  try {
    const parsedUrl = new URL(url);

    return parsedUrl.protocol === "http:" || parsedUrl.protocol === "https:";
  } catch {
    return false;
  }
}

export function buildFailure(
  code: SessionLookupFailure["code"],
  message: string,
): SessionLookupFailure {
  return {
    ok: false,
    code,
    message,
  };
}

export function parseChannelIdFromUrl(url: string): string | null {
  try {
    const parsedUrl = new URL(url);
    const match = parsedUrl.pathname.match(/^\/c\/([^/]+)$/);

    return match?.[1] ?? null;
  } catch {
    return null;
  }
}

export function buildAgentDumpCommand(sessionId: string): string {
  return `agent-dump claude://${sessionId.trim()} -output . -format json`;
}

export async function copyToClipboard(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    return false;
  }
}

import { buildAgentDumpCommand } from "@/lib/command/agent-dump";
import type {
  ConversationRecord,
  QueryErrorCode,
  SessionLookupFailure,
  SessionLookupResult,
} from "@/types/session";

type SerializableLookupResult =
  | {
      ok: true;
      record: ConversationRecord;
    }
  | {
      ok: false;
      code:
        | "DB_OPEN_FAILED"
        | "STORE_MISSING"
        | "NOT_FOUND"
        | "SESSION_ID_MISSING";
      message: string;
    };

function pageLookupConversation(
  targetChannelId: string,
): Promise<SerializableLookupResult> {
  return new Promise((resolve) => {
    const dbRequest = indexedDB.open("FinAgentDB");

    dbRequest.onerror = () => {
      resolve({
        ok: false,
        code: "DB_OPEN_FAILED",
        message: "无法打开 FinAgentDB。",
      });
    };

    dbRequest.onsuccess = async (event) => {
      const db = event.target instanceof IDBOpenDBRequest
        ? event.target.result
        : dbRequest.result;

      if (!db.objectStoreNames.contains("conversations")) {
        resolve({
          ok: false,
          code: "STORE_MISSING",
          message: "FinAgentDB 中不存在 conversations store。",
        });
        return;
      }

      try {
        const transaction = db.transaction("conversations", "readonly");
        const store = transaction.objectStore("conversations");
        const allRecords = await new Promise<ConversationRecord[]>((innerResolve, innerReject) => {
          const getAllRequest = store.getAll();

          getAllRequest.onerror = () => {
            innerReject(new Error("getAll failed"));
          };

          getAllRequest.onsuccess = () => {
            innerResolve((getAllRequest.result as ConversationRecord[]) ?? []);
          };
        });

        const matchedRecord = allRecords.find(
          (record) => record.channelId === targetChannelId,
        );

        if (!matchedRecord) {
          resolve({
            ok: false,
            code: "NOT_FOUND",
            message: "没有找到匹配当前 channelId 的会话。",
          });
          return;
        }

        if (!matchedRecord.sessionId) {
          resolve({
            ok: false,
            code: "SESSION_ID_MISSING",
            message: "找到会话记录，但缺少 sessionId。",
          });
          return;
        }

        resolve({
          ok: true,
          record: {
            channelId: matchedRecord.channelId,
            sessionId: matchedRecord.sessionId,
            title: matchedRecord.title,
            updatedAt: matchedRecord.updatedAt ?? matchedRecord.timestamp,
            timestamp: matchedRecord.timestamp,
          },
        });
      } catch {
        resolve({
          ok: false,
          code: "DB_OPEN_FAILED",
          message: "读取 conversations 数据失败。",
        });
      } finally {
        db.close();
      }
    };
  });
}

function buildLookupFailure(
  code: QueryErrorCode,
  message: string,
): SessionLookupFailure {
  return {
    ok: false,
    code,
    message,
  };
}

export async function readSessionIdFromPage(
  tabId: number,
  channelId: string,
): Promise<SessionLookupResult> {
  try {
    const injectionResults = await chrome.scripting.executeScript({
      target: { tabId },
      world: "MAIN",
      args: [channelId],
      func: pageLookupConversation,
    });

    const result = injectionResults[0]?.result;

    if (!result) {
      return buildLookupFailure(
        "INJECTION_FAILED",
        "脚本已执行，但没有拿到查询结果。",
      );
    }

    if (!result.ok) {
      return buildLookupFailure(result.code, result.message);
    }

    const { record } = result;
    const sessionId = record.sessionId?.trim();

    if (!sessionId) {
      return buildLookupFailure(
        "SESSION_ID_MISSING",
        "找到会话记录，但 sessionId 为空。",
      );
    }

    return {
      ok: true,
      channelId,
      sessionId,
      command: buildAgentDumpCommand(sessionId),
      title: record.title,
      updatedAt: record.updatedAt,
    };
  } catch {
    return buildLookupFailure(
      "INJECTION_FAILED",
      "无法在当前页面执行查询脚本，请确认页面已正常打开。",
    );
  }
}

