import { useEffect, useState } from "react";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { buildFailure, getActiveTab, isInjectablePage } from "@/lib/chrome/active-tab";
import { copyToClipboard } from "@/lib/clipboard/copy";
import { readSessionIdFromPage } from "@/lib/indexeddb/read-session";
import { parseChannelIdFromUrl } from "@/lib/parsing/channel-id";
import type { SessionLookupFailure, SessionLookupResult } from "@/types/session";

type ViewState = { kind: "loading" } | { kind: "ready"; result: SessionLookupResult };

const successCopyLabelDurationMs = 1500;

function getLookupFailureFromTab(tab: chrome.tabs.Tab | null): SessionLookupFailure | null {
  if (!tab?.id) {
    return buildFailure("NO_ACTIVE_TAB", "No active tab was found.");
  }

  if (!tab.url) {
    return buildFailure("INVALID_URL", "The current page does not expose a valid URL.");
  }

  if (!isInjectablePage(tab.url)) {
    return buildFailure(
      "UNSUPPORTED_PAGE",
      "This page does not allow script injection. Open a FinAgent page and try again.",
    );
  }

  const channelId = parseChannelIdFromUrl(tab.url);

  if (!channelId) {
    return buildFailure("INVALID_URL", "The current page path must match /c/:channelId.");
  }

  return null;
}

export function App(): React.JSX.Element {
  const [viewState, setViewState] = useState<ViewState>({ kind: "loading" });
  const [copyMessage, setCopyMessage] = useState<string | null>(null);
  const [isCopying, setIsCopying] = useState(false);

  useEffect(() => {
    let active = true;

    const load = async () => {
      const tab = await getActiveTab();
      const tabFailure = getLookupFailureFromTab(tab);

      if (tabFailure) {
        if (active) {
          setViewState({ kind: "ready", result: tabFailure });
        }
        return;
      }

      const channelId = parseChannelIdFromUrl(tab!.url!);
      const result = await readSessionIdFromPage(tab!.id!, channelId!);

      if (active) {
        setViewState({ kind: "ready", result });
      }
    };

    void load();

    return () => {
      active = false;
    };
  }, []);

  const handleCopy = async (command: string) => {
    setIsCopying(true);

    const copied = await copyToClipboard(command);

    if (!copied) {
      setCopyMessage("Copy failed. Please try again.");
      setIsCopying(false);
      return;
    }

    setCopyMessage("Command copied.");
    setIsCopying(false);

    window.setTimeout(() => {
      setCopyMessage((current) => (current === "Command copied." ? null : current));
    }, successCopyLabelDurationMs);
  };

  const readyResult = viewState.kind === "ready" ? viewState.result : null;

  return (
    <main className="popup-canvas min-h-screen px-4 py-4">
      <Card className="panel-enter overflow-hidden">
        <CardHeader className="gap-4 border-b border-[var(--border)] bg-[linear-gradient(180deg,rgba(255,255,255,0.78),rgba(255,252,247,0.96))] pb-5">
          <div className="flex items-start justify-between gap-4">
            <div className="flex items-start gap-3">
              <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface-muted)] p-2.5 shadow-[inset_0_1px_0_rgba(255,255,255,0.7)]">
                <img alt="FinAgent Owl" className="h-10 w-10 object-contain" src="/logo.svg" />
              </div>

              <div className="space-y-2">
                <p className="text-[11px] font-medium uppercase tracking-[0.26em] text-[var(--muted-foreground)]">
                  FinAgent Owl
                </p>
                <CardTitle>Dump current thread</CardTitle>
                <CardDescription className="max-w-[29ch] text-[13px]">
                  Extract the current session from IndexedDB and copy a ready-to-run command.
                </CardDescription>
              </div>
            </div>

            <div className="rounded-full border border-[var(--border)] bg-[var(--surface-muted)] px-3 py-1 text-[10px] font-medium uppercase tracking-[0.18em] text-[var(--muted-foreground)]">
              popup
            </div>
          </div>
        </CardHeader>

        <CardContent className="space-y-4 pt-4">
          {viewState.kind === "loading" ? (
            <section className="space-y-4">
              <div className="rounded-[24px] border border-[var(--border)] bg-[var(--surface-muted)] p-4">
                <p className="text-sm font-medium text-[var(--foreground)]">Reading FinAgentDB…</p>
                <p className="mt-2 max-w-[34ch] text-sm leading-6 text-[var(--muted-foreground)]">
                  The popup is resolving the current channel ID and preparing a command from the
                  IndexedDB conversation entry.
                </p>
              </div>

              <div className="space-y-3">
                <div className="h-28 animate-pulse rounded-[24px] border border-[var(--border)] bg-[var(--accent-muted)] motion-reduce:animate-none" />
                <div className="grid grid-cols-2 gap-3">
                  <div className="h-24 animate-pulse rounded-[20px] border border-[var(--border)] bg-[var(--surface-muted)] motion-reduce:animate-none" />
                  <div className="h-24 animate-pulse rounded-[20px] border border-[var(--border)] bg-[var(--surface-muted)] motion-reduce:animate-none" />
                </div>
              </div>
            </section>
          ) : readyResult?.ok ? (
            <section className="space-y-4">
              <Button
                aria-label="Copy command"
                className="h-auto w-full items-start justify-start rounded-[24px] px-4 py-4 text-left"
                disabled={isCopying}
                onClick={() => void handleCopy(readyResult.command)}
                variant="outline"
              >
                <div className="w-full space-y-4">
                  <div className="flex items-center justify-between gap-3">
                    <div>
                      <p className="text-[11px] font-medium uppercase tracking-[0.22em] text-[var(--muted-foreground)]">
                        Ready command
                      </p>
                      <p className="mt-1 text-xs leading-5 text-[var(--muted-foreground)]">
                        Click to copy
                      </p>
                    </div>

                    <div className="rounded-full border border-[var(--border)] bg-white/88 px-3 py-1 text-[10px] font-medium uppercase tracking-[0.18em] text-[var(--accent)]">
                      {isCopying ? "Copying" : "Copy command"}
                    </div>
                  </div>

                  <code className="block break-all whitespace-pre-wrap rounded-[20px] border border-[var(--border)] bg-white px-4 py-4 text-[13px] leading-6 text-[var(--foreground)]">
                    {readyResult.command}
                  </code>
                </div>
              </Button>

              <div className="grid grid-cols-2 gap-3">
                <div className="rounded-[20px] border border-[var(--border)] bg-[var(--surface-muted)] p-4">
                  <p className="text-[11px] font-medium uppercase tracking-[0.22em] text-[var(--muted-foreground)]">
                    Channel ID
                  </p>
                  <p className="mt-3 break-all text-[13px] leading-6 text-[var(--foreground)]">
                    {readyResult.channelId}
                  </p>
                </div>

                <div className="rounded-[20px] border border-[var(--border)] bg-[var(--surface-muted)] p-4">
                  <p className="text-[11px] font-medium uppercase tracking-[0.22em] text-[var(--muted-foreground)]">
                    Session ID
                  </p>
                  <p className="mt-3 break-all text-[13px] leading-6 text-[var(--foreground)]">
                    {readyResult.sessionId}
                  </p>
                </div>
              </div>

              {readyResult.title ? (
                <div className="rounded-[20px] border border-[var(--border)] bg-[var(--surface-muted)] p-4">
                  <p className="text-[11px] font-medium uppercase tracking-[0.22em] text-[var(--muted-foreground)]">
                    Title
                  </p>
                  <div className="mt-3 flex items-start gap-3">
                    <span className="mt-1 h-2.5 w-2.5 rounded-full bg-[var(--warm)]" />
                    <p className="text-[13px] leading-6 text-[var(--foreground)]">
                      {readyResult.title}
                    </p>
                  </div>
                </div>
              ) : null}

              <div aria-live="polite">
                {copyMessage ? (
                  <Alert className="status-flash">
                    <AlertTitle>Status</AlertTitle>
                    <AlertDescription>{copyMessage}</AlertDescription>
                  </Alert>
                ) : (
                  <p className="text-xs leading-6 text-[var(--muted-foreground)]">
                    The command is copied only. It is not executed by the extension.
                  </p>
                )}
              </div>

              <div className="rounded-[20px] border border-dashed border-[var(--border-strong)] bg-[linear-gradient(180deg,rgba(255,255,255,0.66),rgba(255,247,236,0.8))] px-4 py-3">
                <p className="text-[11px] font-medium uppercase tracking-[0.2em] text-[var(--muted-foreground)]">
                  Internal workflow
                </p>
                <p className="mt-2 text-xs leading-6 text-[var(--muted-foreground)]">
                  Use the copied command in your terminal to export the current thread as JSON.
                </p>
              </div>
            </section>
          ) : (
            <section className="space-y-4">
              <Alert variant="destructive">
                <AlertTitle>Unable to prepare command</AlertTitle>
                <AlertDescription>{readyResult?.message}</AlertDescription>
