                    disabled={isCopying}
                    onClick={() => void handleCopy(readyResult.command)}
                    variant="outline"
                  >
                    {isCopying ? "Copying..." : "Copy"}
                  </Button>
                </div>

                <div className="mt-2 rounded-[16px] border border-[var(--border)] bg-white px-3 py-3">
                  <code className="block break-all whitespace-pre-wrap text-[12px] leading-6 text-[var(--foreground)]">
                    {readyResult.command}
                  </code>
                </div>
              </div>

              <details
                className="rounded-[18px] border border-[var(--border)] bg-[var(--surface-muted)] px-3 py-2 open:pb-3"
                open
              >
                <summary className="cursor-pointer list-none text-[11px] font-medium uppercase tracking-[0.18em] text-[var(--foreground)] [&::-webkit-details-marker]:hidden">
                  <span className="inline-flex items-center gap-2">
                    <span className="text-[10px] text-[var(--muted-foreground)]">▼</span>
                    Session Info
                  </span>
                </summary>

