import { useEffect, useState } from "react";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { buildFailure, getActiveTab, isInjectablePage } from "@/lib/chrome/active-tab";
import { copyToClipboard } from "@/lib/clipboard/copy";
import { readSessionIdFromPage } from "@/lib/indexeddb/read-session";
import { parseChannelIdFromUrl } from "@/lib/parsing/channel-id";
import type { SessionLookupFailure, SessionLookupResult } from "@/types/session";

type ViewState = { kind: "loading" } | { kind: "ready"; result: SessionLookupResult };

const successCopyLabelDurationMs = 3000;

function CopyIcon(): React.JSX.Element {
  return (
    <svg aria-hidden="true" className="h-4 w-4" fill="none" viewBox="0 0 24 24">
      <rect height="11" rx="2" stroke="currentColor" strokeWidth="1.8" width="11" x="9" y="9" />
      <path
        d="M7 15H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h7a2 2 0 0 1 2 2v1"
        stroke="currentColor"
        strokeLinecap="round"
        strokeWidth="1.8"
      />
    </svg>
  );
}

function CheckIcon(): React.JSX.Element {
  return (
    <svg aria-hidden="true" className="h-4 w-4" fill="none" viewBox="0 0 24 24">
      <path
        d="m5 12 4.2 4.2L19 6.8"
        stroke="currentColor"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth="2"
      />
    </svg>
  );
}

function InfoRow({ label, value }: { label: string; value: string }): React.JSX.Element {
  return (
    <div className="grid grid-cols-[68px_minmax(0,1fr)] items-start gap-3 border-t border-[var(--border)] py-2 first:border-t-0 first:pt-0 last:pb-0">
      <span className="text-[11px] font-medium uppercase tracking-[0.16em] text-[var(--muted-foreground)]">
        {label}
      </span>
      <span className="break-all text-[12px] leading-6 text-[var(--foreground)]">{value}</span>
    </div>
  );
}

function getLookupFailureFromTab(tab: chrome.tabs.Tab | null): SessionLookupFailure | null {
  if (!tab?.id) {
    return buildFailure("NO_ACTIVE_TAB", "No active tab was found.");
  }

  if (!tab.url) {
    return buildFailure("INVALID_URL", "The current page does not expose a valid URL.");
  }

  if (!isInjectablePage(tab.url)) {
    return buildFailure(
      "UNSUPPORTED_PAGE",
      "This page does not allow script injection. Open a FinAgent page and try again.",
    );
  }

  const channelId = parseChannelIdFromUrl(tab.url);

  if (!channelId) {
    return buildFailure("INVALID_URL", "The current page path must match /c/:channelId.");
  }

  return null;
}

export function App(): React.JSX.Element {
  const [viewState, setViewState] = useState<ViewState>({ kind: "loading" });
  const [isCopying, setIsCopying] = useState(false);
  const [isCopied, setIsCopied] = useState(false);

  useEffect(() => {
    let active = true;

    const load = async () => {
      const tab = await getActiveTab();
      const tabFailure = getLookupFailureFromTab(tab);

      if (tabFailure) {
        if (active) {
          setViewState({ kind: "ready", result: tabFailure });
        }
        return;
      }

      const activeTab = tab as chrome.tabs.Tab;
      const channelId = parseChannelIdFromUrl(activeTab.url!);
      const result = await readSessionIdFromPage(activeTab.id!, channelId!);

      if (active) {
        setViewState({ kind: "ready", result });
      }
    };

    void load();

    return () => {
      active = false;
    };
  }, []);

  const handleCopy = async (command: string) => {
    setIsCopying(true);
    setIsCopied(false);

    const copied = await copyToClipboard(command);

    if (!copied) {
      setIsCopying(false);
      return;
    }

    setIsCopied(true);
    setIsCopying(false);

    window.setTimeout(() => {
      setIsCopied(false);
    }, successCopyLabelDurationMs);
  };

  const readyResult = viewState.kind === "ready" ? viewState.result : null;

  return (
    <main className="popup-canvas min-h-screen px-3 py-3">
      <Card className="panel-enter overflow-hidden">
        <CardHeader className="gap-2 border-b border-[var(--border)] bg-white/92 pb-3">
          <div className="flex items-center gap-3">
            <img alt="FinAgent Owl" className="h-8 w-8 shrink-0 object-contain" src="/logo.svg" />
            <div className="min-w-0 flex-1">
              <p className="text-[10px] font-medium uppercase tracking-[0.22em] text-[var(--muted-foreground)]">
                FinAgent Owl
              </p>
              <CardTitle className="mt-1 text-[22px] leading-[1.1]">Dump Current Thread</CardTitle>
            </div>
          </div>
        </CardHeader>

        <CardContent className="space-y-3 pt-3">
          {viewState.kind === "loading" ? (
            <section className="space-y-3">
              <div className="rounded-[18px] border border-[var(--border)] bg-[var(--surface-muted)] p-3">
                <p className="text-[12px] font-medium text-[var(--foreground)]">
                  Reading FinAgentDB...
                </p>
              </div>

              <div className="h-28 animate-pulse rounded-[18px] border border-[var(--border)] bg-[var(--accent-muted)] motion-reduce:animate-none" />
              <div className="h-16 animate-pulse rounded-[18px] border border-[var(--border)] bg-[var(--surface-muted)] motion-reduce:animate-none" />
            </section>
          ) : readyResult?.ok ? (
            <section className="space-y-3">
              <div className="rounded-[18px] border border-[var(--border)] bg-[var(--surface-muted)] p-3">
                <div className="flex items-center justify-between gap-3">
                  <p className="text-[11px] font-medium uppercase tracking-[0.2em] text-[var(--muted-foreground)]">
                    agent-dump
                  </p>

                  <div className="flex items-center gap-2">
                    {isCopied ? (
                      <span className="status-flash rounded-full border border-[var(--border)] bg-white px-2.5 py-1 text-[10px] font-medium uppercase tracking-[0.14em] text-[var(--accent)]">
                        Copied
                      </span>
                    ) : null}

                    <button
                      aria-label="Copy command"
                      className="inline-flex h-9 w-9 cursor-pointer items-center justify-center rounded-full border border-[var(--border-strong)] bg-white text-[var(--foreground)] shadow-[0_6px_18px_rgba(34,46,56,0.08)] transition-[background-color,border-color,color,box-shadow,transform] duration-200 hover:border-[var(--accent)] hover:bg-[var(--surface)] hover:text-[var(--accent)] hover:shadow-[0_10px_20px_rgba(34,46,56,0.12)] active:translate-y-px focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)] focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                      disabled={isCopying}
                      onClick={() => void handleCopy(readyResult.command)}
                      type="button"
                    >
                      {isCopied ? <CheckIcon /> : <CopyIcon />}
                    </button>
                  </div>
                </div>

                <div className="mt-2 rounded-[16px] border border-[var(--border)] bg-white px-3 py-3">
                  <code className="block break-all whitespace-pre-wrap text-[11px] leading-6 text-[var(--foreground)]">
                    {readyResult.command}
                  </code>
                </div>
              </div>

              <div className="rounded-[18px] border border-[var(--border)] bg-[var(--surface-muted)] px-3 py-2 pb-3">
                <p className="text-[11px] font-medium uppercase tracking-[0.18em] text-[var(--foreground)]">
                  Session Info
                </p>

                <div className="mt-3 space-y-0">
                  {readyResult.title ? <InfoRow label="Title" value={readyResult.title} /> : null}
                  <InfoRow label="Channel" value={readyResult.channelId} />
                  <InfoRow label="Session" value={readyResult.sessionId} />
                </div>
              </div>

              <p className="text-[11px] leading-5 text-[var(--muted-foreground)]">
                The extension only copies the command. It does not execute it.
              </p>
            </section>
          ) : (
            <section className="space-y-3">
              <div className="rounded-[18px] border border-[var(--destructive-border)] bg-[var(--destructive-bg)] px-4 py-3 text-sm shadow-[0_10px_24px_rgba(25,36,46,0.08)]">
                <p className="font-medium tracking-[-0.01em] text-[var(--destructive-foreground)]">
                  Unable to prepare command
                </p>
                <p className="mt-1 text-sm leading-6 text-[var(--destructive-foreground)] opacity-90">
                  {readyResult?.message}
                </p>
              </div>

              <div className="rounded-[18px] border border-[var(--border)] bg-[var(--surface-muted)] p-3">
                <p className="text-[11px] font-medium uppercase tracking-[0.18em] text-[var(--muted-foreground)]">
                  Expected Page
                </p>
                <p className="mt-2 text-[12px] leading-6 text-[var(--foreground)]">
                  Open a FinAgent conversation page with a URL that matches
                  <code className="mx-1 rounded bg-white px-1.5 py-0.5 text-[12px]">
                    /c/:channelId
                  </code>
                  and try again.
                </p>
              </div>
            </section>
          )}
        </CardContent>
      </Card>
    </main>
  );
}

