    setIsCopying(true);
    setIsCopied(false);

    const copied = await copyToClipboard(command);

    if (!copied) {
      setIsCopying(false);
      return;
    }

    setIsCopied(true);
    setIsCopying(false);

    window.setTimeout(() => {
      setIsCopied(false);
    }, successCopyLabelDurationMs);
  };

  const readyResult = viewState.kind === "ready" ? viewState.result : null;

  return (
