                  <InfoRow
                    icon={<SessionInfoIcon />}
                    label="Session"
                    value={readyResult.sessionId}
                  />
                </div>
              </section>

              <div className="rounded-[16px] border border-[rgba(68,127,228,0.18)] bg-[var(--info-banner)] px-4 py-4">
                <div className="flex items-start gap-3">
                  <InfoBannerIcon />
